CREATE OR REPLACE FUNCTION private.base_supported(p text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT p=ANY(ARRAY['sale_work.access','sale_work.view_own','sale_work.manage_settings','sale_work.manage_credentials','sale_work.view_audit','biz.crm_use']) $$;
CREATE OR REPLACE FUNCTION private.base_next_transition(c jsonb) RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH objects AS (SELECT value r FROM jsonb_array_elements(c->'grants') UNION ALL SELECT value FROM jsonb_array_elements(c->'memberships') UNION ALL SELECT value FROM jsonb_array_elements(c->'bindings') UNION ALL SELECT value FROM jsonb_array_elements(c->'defaults') UNION ALL SELECT value FROM jsonb_array_elements(c->'bundles') UNION ALL SELECT q FROM jsonb_array_elements(c->'defaults') b CROSS JOIN LATERAL jsonb_array_elements(b->'rules') q UNION ALL SELECT q FROM jsonb_array_elements(c->'bundles') b CROSS JOIN LATERAL jsonb_array_elements(b->'rules') q),dates AS (SELECT nullif(r->>'starts_at','')::timestamptz t FROM objects UNION ALL SELECT nullif(r->>'ends_at','')::timestamptz FROM objects) SELECT min(t) FROM dates WHERE t>now() $$;
DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.base_permissions_effective(uuid)'::regprocedure) INTO d;d:=replace(d,$s$'server_now',now(),'permissions'$s$,$s$'server_now',now(),'next_transition_at',private.base_next_transition(private.base_config()),'permissions'$s$);EXECUTE d;END $patch$;
CREATE OR REPLACE FUNCTION private.base_config_diff(a jsonb,b jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('section',k,'before',a->k,'after',b->k)),'[]') FROM unnest(ARRAY['units','titles','memberships','defaults','bundles','grants','bindings']) k WHERE a->k IS DISTINCT FROM b->k $$;
DO $patch$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.base_org_preview(bigint,jsonb)'::regprocedure) INTO d;d:=replace(d,$s$'impact',impact,'expires_at'$s$,$s$'impact',impact,'config_diff',private.base_config_diff(private.base_config(),_config),'next_transition_at',private.base_next_transition(_config),'expires_at'$s$);EXECUTE d;END $patch$;
REVOKE ALL ON FUNCTION private.base_next_transition(jsonb),private.base_config_diff(jsonb,jsonb) FROM PUBLIC,anon,authenticated;